import {
  isProgramError,
  type Address,
  type HasAddress,
  type SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM,
  type SolanaError,
} from "@solana/kit";
import { TALLER_PROGRAM_ADDRESS } from "../programs";

/** NoOwner: Error, no eres el owner del taller */
export const TALLER_ERROR__NO_OWNER = 0x1770; // 6000
/** NoOrden: Error, la orden no esta en el registro del equipo */
export const TALLER_ERROR__NO_ORDEN = 0x1771; // 6001
/** LimiteAlcanzado: Error, se alcanzo el limite maximo de 10 elementos */
export const TALLER_ERROR__LIMITE_ALCANZADO = 0x1772; // 6002

export type TallerError =
  | typeof TALLER_ERROR__LIMITE_ALCANZADO
  | typeof TALLER_ERROR__NO_ORDEN
  | typeof TALLER_ERROR__NO_OWNER;

let tallerErrorMessages: Record<TallerError, string> | undefined;
if (process.env["NODE_ENV"] !== "production") {
  tallerErrorMessages = {
    [TALLER_ERROR__LIMITE_ALCANZADO]: `Error, se alcanzo el limite maximo de 10 elementos`,
    [TALLER_ERROR__NO_ORDEN]: `Error, la orden no esta en el registro del equipo`,
    [TALLER_ERROR__NO_OWNER]: `Error, no eres el owner del taller`,
  };
}

export function getTallerErrorMessage(code: TallerError): string {
  if (process.env["NODE_ENV"] !== "production") {
    return (tallerErrorMessages as Record<TallerError, string>)[code];
  }

  return "Error message not available in production bundles.";
}

export function isTallerError<TProgramErrorCode extends TallerError>(
  error: unknown,
  transactionMessage: {
    instructions: Record<number, { programAddress: Address }>;
  },
  code?: TProgramErrorCode,
  config: { programAddress?: Address | HasAddress } = {},
): error is SolanaError<typeof SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM> &
  Readonly<{ context: Readonly<{ code: TProgramErrorCode }> }> {
  const programAddressInput = config.programAddress ?? TALLER_PROGRAM_ADDRESS;
  const programAddress =
    typeof programAddressInput === "string"
      ? programAddressInput
      : programAddressInput.address;
  return isProgramError<TProgramErrorCode>(
    error,
    transactionMessage,
    programAddress,
    code,
  );
}
